{
  "name": "@kevincojean/opencode-mempalace",
  "version": "0.4.2",
  "description": "OpenCode plugin for MemPalace memory system — auto-registers MCP server, injects memory protocol into system prompt, and loads context on session start",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "type": "module",
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun --format esm && tsc -p tsconfig.build.json",
    "check": "tsc --noEmit",
    "test": "bun test",
    "prepublishOnly": "bun run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mempalace",
    "memory",
    "mcp",
    "knowledge-graph"
  ],
  "author": "Kevin Cojean",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/kevincojean/opencode-mempalace"
  },
  "publishConfig": {
    "provenance": true
  },
  "bugs": "https://github.com/kevincojean/opencode-mempalace/issues",
  "homepage": "https://github.com/kevincojean/opencode-mempalace#readme",
  "devDependencies": {
    "@opencode-ai/plugin": "^1.3.13",
    "@tsconfig/bun": "^1.0.10",
    "@types/bun": "^1.3.10",
    "typescript": "^5.8.2"
  },
  "dependencies": {
    "zod": "^4.3.6"
  }
}
